CREATE OR REPLACE FUNCTION public.submit_post_evidence(_post uuid,_purpose text,_paths text[]) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; path text; admin_id uuid; mobile text; expected integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; SELECT phone INTO mobile FROM public.profiles WHERE id=auth.uid(); IF mobile IS NULL OR mobile !~ '^[6-9][0-9]{9}$' THEN RAISE EXCEPTION 'MOBILE_REQUIRED'; END IF; IF NOT EXISTS(SELECT 1 FROM public.posts WHERE id=_post AND user_id=auth.uid()) THEN RAISE EXCEPTION 'OWN_POST_REQUIRED'; END IF; expected:=CASE _purpose WHEN 'early_publication' THEN 5 WHEN 'notifications' THEN 10 ELSE 0 END; IF expected=0 OR cardinality(_paths)<>expected OR (SELECT count(DISTINCT p) FROM unnest(_paths)p)<>expected THEN RAISE EXCEPTION 'STATUS_AND_SHARING_IMAGES_REQUIRED'; END IF; FOREACH path IN ARRAY _paths LOOP IF path NOT LIKE auth.uid()::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='sharing-evidence' AND name=path) OR EXISTS(SELECT 1 FROM public.post_sharing_evidence WHERE path=ANY(paths)) THEN RAISE EXCEPTION 'INVALID_EVIDENCE'; END IF; END LOOP; admin_id:=public.support_admin_id(); IF admin_id IS NULL THEN RAISE EXCEPTION 'ADMIN_UNAVAILABLE'; END IF; INSERT INTO public.post_sharing_evidence(user_id,post_id,purpose,paths) VALUES(auth.uid(),_post,_purpose,_paths) RETURNING id INTO result; INSERT INTO public.messages(sender_id,receiver_id,post_id,body,needs_admin) VALUES(auth.uid(),admin_id,_post,'స్థితి, నాలుగు సమూహాల చిత్రాలు పరిశీలించండి · Review sharing evidence: '||result::text,true); RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.public_referral_vip_board() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('limit',10,'event_label',coalesce((SELECT event_label FROM public.referral_vip_campaign WHERE id),'నిర్వాహకుడు ప్రకటిస్తారు'),'totals',jsonb_build_object('TG',NULL,'AP',NULL),'rows',CASE WHEN now()<'2026-11-22 23:00:00+05:30'::timestamptz THEN '[]'::jsonb ELSE coalesce((SELECT jsonb_agg(rowdata ORDER BY place) FROM (SELECT r.rank_no place,jsonb_build_object('rank',r.rank_no,'count',r.joins,'name',c.display_name,'region',c.region,'photo_path',CASE WHEN c.photo_consent AND s.published AND s.photo_path LIKE s.user_id::text||'/%' THEN s.photo_path ELSE '' END) rowdata FROM public.referral_vip_ranks() r JOIN public.referral_board_consent c ON c.user_id=r.user_id LEFT JOIN public.service_profiles s ON s.user_id=r.user_id WHERE c.published AND c.region IN('TG','AP') AND r.rank_no<=10) a),'[]'::jsonb) END) $$;